import {promotionsView,promotionRows,promotionOrders,promoForm,blankCampaign} from './promotions-admin.js';
import {teamView,teamRows,personForm,tasksView,taskList,chatView,chatMessages} from './team-admin.js';
import {showPromotion} from './promotion-popup.js';
import {showOrderConfirmation} from './order-confirmation.js';
import {products as originals,money} from './catalog.js';
import {analytics,insights,statuses,statusLabels,promotionAnalytics} from './commerce.js';
import * as auth from './auth-client.js';
const $=(s,r=document)=>r.querySelector(s),$$=(s,r=document)=>[...r.querySelectorAll(s)];
const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const e=escape,root=$('#workspace'),page=document.body.dataset.page,isAdmin=page==='admin',demo=false; // The sample dashboards are gone: this is a real shop, and an
// invented admin panel was reachable by anyone who typed ?demo=1. Kept as a
// constant so the guards below still read as guards rather than disappearing.
const state={regions:null,team:[],teamQuery:'',tasks:[],staff:[],messages:[],promoPeriod:30,promoFilter:'all',promoQuery:'',promotions:[],campaign:blankCampaign,checkout:null,user:null,products:[],orders:[],customers:[],activity:[],connections:{},view:location.hash.slice(1)||'overview',query:'',filter:'all',days:30,selectedOrder:null,events:[],lastCheck:null};
let config={auth:'chatgpt'},timer,noticeTimer,requestKey=crypto.randomUUID();
const date=x=>x?new Date(x).toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric'}):'Not set';
const time=x=>x?new Date(x).toLocaleString('en-GB',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'}):'';
const badge=(status,label)=>`<span class="status ${e(status)}">${e(label||statusLabels[status]||status)}</span>`;
const image=p=>`<img src="${e(p.image)}" alt="${e(p.name)} — ${e(p.color)}" loading="lazy">`;
const button=(text,action,cls='btn')=>`<button class="${cls}" data-action="${action}">${text}</button>`;
const empty=(title,copy,action='')=>`<div class="empty"><p class="eyebrow">A LITTLE ROOM FOR WHAT’S NEXT</p><h2>${title}</h2><p>${copy}</p>${action}</div>`;
function notify(message){$('#notice').textContent=message;$('#notice').classList.add('show');clearTimeout(noticeTimer);noticeTimer=setTimeout(()=>$('#notice').classList.remove('show'),5000);}
async function api(path,options={}){const token=await auth.getToken();const authHeader=token?{Authorization:'Bearer '+token}:{};const response=await fetch(path,{...options,headers:options.body instanceof Blob?{...authHeader}:{'Content-Type':'application/json',...authHeader,...options.headers}});let result;try{result=await response.json();}catch{throw Error('The store connection is unavailable. Please try again.');}if(!response.ok){const error=Error(result.error||'Unable to complete this request.');error.status=response.status;throw error;}return result;}
function writeAllowed(){if(!demo)return true;notify('This is sample data. Sign in to manage your real store.');return false;}
const authLink=target=>`/login/?return_to=${encodeURIComponent(target)}`;
const signOut='#sign-out';
// Where to land after a magic link or Google redirect. Only same-site paths are
// honoured, so a crafted ?return_to cannot bounce a signed-in user off-site.
function returnTarget(){
 const raw=new URLSearchParams(location.search).get('return_to')||'';
 return raw.startsWith('/')&&!raw.startsWith('//')?raw:'/dashboard/';
}
let authMode='password';
// Where to send someone once they are signed in. The owner wants the control
// room, not the customer dashboard, and previously had to know to type /admin/.
// An explicit ?return_to is honoured as-is.
async function destinationAfterSignIn(){
 if(new URLSearchParams(location.search).get('return_to'))return returnTarget();
 try{const {user}=await api('/api/me');return user&&user.admin?'/admin/':'/dashboard/';}
 catch{return '/dashboard/';}
}
async function submitAuth(form,action){
 const error=$('.error',form),button=$('button',form);
 const set=m=>{if(error)error.textContent=m;};
 set('');button.disabled=true;
 try{
  await action();
 }catch(err){set(err.message);}
 finally{button.disabled=false;}
}
async function boot(){
 const redirect=auth.consumeRedirect();
 if(redirect?.error){notify(redirect.error);}
 else if(redirect?.session&&['login','signup'].includes(page)){location.replace(await destinationAfterSignIn());return;}
 try{config=await api('/api/config');state.connections.ai=config.ai;state.connections.uploads=config.uploads;const result=await api('/api/me');state.user=result.user;
 if(['login','signup'].includes(page)){renderAuth();return;}
 if(!state.user){renderGate();return;}
 if(isAdmin&&!state.user.admin){renderGate(true);return;}
 await loadData();render();if(new URLSearchParams(location.search).get('checkout')==='1'&&!isAdmin)checkout();
 }catch(error){root.innerHTML=`<main id="workspace-main" class="initial-panel"><p class="eyebrow">LYVERNE / YOUR SPACE</p><h1>A MOMENT, PLEASE.</h1><p class="error">${e(error.message)}</p><div class="actions"><button class="btn" data-action="retry">Try again ↗︎</button></div></main>`;}
}
async function loadData(){if(isAdmin){const [overview,promotions]=await Promise.all([api('/api/admin/overview'),api('/api/admin/promotions')]);Object.assign(state,overview,promotions);}else{const [o,p]=await Promise.all([api('/api/orders'),api('/api/products')]);state.orders=o.orders;state.products=p.products;state.selectedOrder=state.selectedOrder||o.orders[0]?.id;if(state.selectedOrder)await loadTracking();}state.lastCheck=new Date();}
async function loadTracking(){const data=await api('/api/orders/'+encodeURIComponent(state.selectedOrder));state.orders=state.orders.map(o=>o.id===data.order.id?data.order:o);state.events=data.events;state.lastCheck=new Date();}
function authForms(signup){
 const target=e(returnTarget());
 const password=`<form id="auth-password" autocomplete="on"><label>Email<input name="email" type="email" autocomplete="email" required maxlength="320"></label>${signup?'<label>Your name<input name="name" autocomplete="name" required maxlength="100"></label>':''}<label>Password<input name="password" type="password" autocomplete="${signup?'new-password':'current-password'}" required minlength="8" maxlength="72"></label><button class="btn orange" type="submit">${signup?'CREATE ACCOUNT':'SIGN IN'} ↗︎</button><p class="error" role="alert"></p></form>${signup?'':'<button class="text-btn" data-action="forgot">Forgotten your password?</button>'}`;
 const magic=`<form id="auth-magic"><label>Email<input name="email" type="email" autocomplete="email" required maxlength="320"></label><button class="btn orange" type="submit">EMAIL ME A LINK ↗︎</button><p class="error" role="alert"></p><p class="auth-note">We send a one-time link. No password needed.</p></form>`;
 return `<div class="auth-tabs" role="tablist"><button role="tab" data-mode="password" aria-current="${authMode==='password'?'page':'false'}">PASSWORD</button><button role="tab" data-mode="magic" aria-current="${authMode==='magic'?'page':'false'}">EMAIL LINK</button></div>${authMode==='password'?password:magic}<div class="auth-divider">OR</div><button class="btn ghost google-btn" data-action="google"><svg class="g-mark" viewBox="0 0 18 18" width="16" height="16" aria-hidden="true"><path fill="#4285F4" d="M17.64 9.2c0-.64-.06-1.25-.16-1.84H9v3.48h4.84a4.14 4.14 0 0 1-1.8 2.72v2.26h2.92c1.7-1.57 2.68-3.88 2.68-6.62Z"/><path fill="#34A853" d="M9 18c2.43 0 4.47-.8 5.96-2.18l-2.92-2.26c-.8.54-1.84.86-3.04.86-2.34 0-4.32-1.58-5.03-3.7H.94v2.33A9 9 0 0 0 9 18Z"/><path fill="#FBBC05" d="M3.97 10.72a5.4 5.4 0 0 1 0-3.44V4.95H.94a9 9 0 0 0 0 8.1l3.03-2.33Z"/><path fill="#EA4335" d="M9 3.58c1.32 0 2.5.46 3.44 1.35l2.58-2.58C13.46.9 11.42 0 9 0A9 9 0 0 0 .94 4.95l3.03 2.33C4.68 5.16 6.66 3.58 9 3.58Z"/></svg>CONTINUE WITH GOOGLE</button><input type="hidden" id="auth-return" value="${target}">`;
}
function renderAuth(){
 const signup=page==='signup';const done=state.user;
 root.innerHTML=`<main id="workspace-main" class="auth-layout"><section class="auth-art" aria-label="Lyverne everyday style"><img src="/assets/studio-editorial.png" alt="Lyverne black tee styled with cream trousers"><div class="roundel" aria-hidden="true">A LITTLE<br>MORE YOU.</div><div class="auth-art-copy"><p class="eyebrow">YOUR EVERYDAY, RECONSIDERED.</p><h2>GOOD TO<br>HAVE YOU HERE.</h2></div></section><section class="auth-form-wrap"><div class="auth-tabs"><a href="/login/" ${!signup?'aria-current="page"':''}>SIGN IN</a><a href="/signup/" ${signup?'aria-current="page"':''}>CREATE ACCOUNT</a></div><p class="eyebrow">YOUR ACCOUNT</p><h1>${signup?'MAKE YOURSELF<br>AT HOME.':'WELCOME<br>BACK.'}</h1><p class="auth-copy">${signup?'Keep your favorite pieces close. Follow every order. Find a little more you.':'Your pieces, your orders, your next everyday favorite.'}</p>${done?`<div class="auth-success"><p class="small">Signed in as ${e(done.email)}</p>${signup?`<form id="signup-form"><label>Your name<input name="name" maxlength="100" value="${e(done.name)}" autocomplete="name" required></label><button class="btn orange">CREATE MY LYVERNE PROFILE ↗︎</button><p class="error" role="alert"></p></form>`:`${done.admin?'<a class="btn orange" href="/admin/">OPEN STORE ADMIN ↗︎</a><a class="text-btn" href="/dashboard/">My account ↗︎</a>':'<a class="btn orange" href="/dashboard/">OPEN MY ACCOUNT ↗︎</a>'}<button class="text-btn" data-action="sign-out">Sign out</button>`}</div>`:authForms(signup)}</section></main>`;
}
function renderGate(denied=false){root.innerHTML=`<main id="workspace-main" class="auth-layout"><section class="auth-art"><img src="/assets/studio-editorial.png" alt="Lyverne everyday style"><div class="auth-art-copy"><p class="eyebrow">${isAdmin?'STORE ADMIN.':'YOUR ACCOUNT'}</p><h2>${isAdmin?'A LITTLE<br>MORE CONTROL.':'YOUR STYLE.<br>YOUR SPACE.'}</h2></div></section><section class="auth-form-wrap"><p class="eyebrow">${isAdmin?'LYVERNE / STORE ADMIN':'LYVERNE / YOUR SPACE'}</p><h1>${denied?'OWNER<br>ACCESS ONLY.':isAdmin?'HELLO,<br>LYVERNE.':'YOUR EVERYDAY.<br>ALL TOGETHER.'}</h1><p class="auth-copy">${denied?'This account is a customer account. Store admin is reserved for the store owner.':isAdmin?'Orders, pieces, people and a clearer picture of your business. Sign in with the store owner account.':'Sign in to follow your orders, keep your details up to date, and save your favorite pieces.'}</p><a class="btn orange" href="${denied?'/dashboard/':authLink(location.pathname+location.search+location.hash)}">${denied?'OPEN MY ACCOUNT':'SIGN IN'} ↗︎</a>${!isAdmin?'<p class="auth-note">New here? <a class="text-btn" href="/signup/">Create your account</a></p>':''}</section></main>`;}
const customerNav=[['overview','⌂','Overview'],['orders','▤','My orders'],['tracking','↗︎','Track an order'],['saved','♡','Saved pieces'],['addresses','⌖','Delivery details'],['profile','○','My profile']];
// The team tabs sit after Customers because they are about the people running
// the store rather than the storefront. People is visible to every admin -- the
// chief-only part is the controls inside it, not knowing who the team is.
const adminTabs=[['overview','⌂','Overview'],['orders','▤','Orders'],['products','▧','Products'],['inventory','≡','Inventory'],['promotions','%','Promotions'],['customers','♧','Customers'],['team','☍','People'],['tasks','✓','Work board'],['chat','✉︎','Team thread'],['analytics','↗︎','Analytics'],['assistant','✳','AI companion'],['activity','◷','Activity log'],['settings','⚙','Settings']];
const adminNav=adminTabs;
function render(){
 clearTimeout(timer);if(['login','signup'].includes(page)){renderAuth();return;}
 const nav=isAdmin?adminNav:customerNav;if(!nav.some(n=>n[0]===state.view))state.view='overview';
 root.innerHTML=`<div class="workspace-layout"><aside class="sidebar"><span class="side-label">${isAdmin?'STORE ADMIN':'YOUR EVERYDAY'}</span><nav class="side-nav" aria-label="${isAdmin?'Admin':'Account'} navigation">${nav.map(([id,icon,label])=>`<button data-tab="${id}" ${state.view===id?'aria-current="page"':''}><span class="nav-icon" aria-hidden="true">${icon}</span>${label}</button>`).join('')}</nav><div class="side-note"><span>${demo?'SAMPLE ACCOUNT':isAdmin?'STORE OWNER':'YOUR LYVERNE ACCOUNT'}</span><strong>${e(state.user.name)}</strong><a href="${demo?'/login/':signOut}">${demo?'Sign in to your account':'Sign out'} ↗︎</a></div></aside><main id="workspace-main" class="work-area"><div class="work-topline"><p class="eyebrow">LYVERNE / ${isAdmin?'OPERATIONS':'MY ACCOUNT'}</p><span class="eyebrow">${new Date().toLocaleDateString('en-GB',{day:'2-digit',month:'short',year:'numeric'})}</span></div>${demo?`<div class="mode-strip"><span>SAMPLE DATA · Explore the design. Changes here are not saved.</span><a href="/${isAdmin?'admin':'login'}/">${isAdmin?'OWNER SIGN IN':'SIGN IN'} ↗︎</a></div>`:''}<div id="view-content">${viewContent()}</div></main></div>`;
 if(state.view==='chat')scrollChat();
 if(!demo&&!isAdmin&&['overview','tracking','orders'].includes(state.view)&&state.selectedOrder)timer=setTimeout(refreshTracking,15000);
}
function heading(title,copy='',action=''){return `<div class="work-heading"><div><h1>${title}</h1>${copy?`<p>${copy}</p>`:''}</div>${action?`<div class="actions">${action}</div>`:''}</div>`;}
function stats(items){return `<div class="stats">${items.map(([label,value,sub])=>`<div class="stat"><span class="stat-label">${label}</span><strong>${value}</strong><small>${sub}</small></div>`).join('')}</div>`;}
function promoReport(){return {...promotionAnalytics(state.orders,state.promoPeriod),generatedAt:state.lastCheck?.getTime()||Date.now()};}
function refreshPromoRows(){$('#promo-results').innerHTML=promotionRows(state.promotions,promoReport(),money,state.promoFilter,state.promoQuery);}
function overview(){return isAdmin?adminOverview():customerOverview();}
function viewContent(){return ({overview,orders:ordersView,tracking:trackingView,saved:savedView,addresses:addressesView,profile:profileView,products:productsView,inventory:inventoryView,customers:customersView,team:()=>teamView(state.team,teamContext()),tasks:()=>tasksView(state.tasks,state.staff,teamContext()),chat:()=>chatView(state.messages,{youId:state.user.id,you:state.user}),analytics:analyticsView,assistant:assistantView,promotions:()=>promotionsView(state.promotions,state.campaign,money,{report:promoReport(),period:state.promoPeriod,filter:state.promoFilter,query:state.promoQuery}),activity:activityView,settings:settingsView}[state.view]||overview)();}
function customerOverview(){
 const order=state.orders.find(o=>!['delivered','cancelled'].includes(o.status))||state.orders[0];
 return heading(`HEY, ${e(state.user.name.split(' ')[0])}.`,'Your everyday, all in one place.',`<a class="pill-link" href="/collection/">Find your next favorite ↗︎</a>`)+stats([['Orders',state.orders.length,'Your Lyverne collection'],['On the way',state.orders.filter(o=>['shipped','out-for-delivery'].includes(o.status)).length,'Follow every step'],['Saved pieces',wishlist().length,'A little inspiration'],['Your circle','LYVERNE','Good to have you here.']])+`<div class="dash-grid"><div>${order?trackingCard(order):`<div class="panel">${empty('YOUR FIRST PIECE AWAITS.','When you place an order, its journey will appear right here.','<a class="btn orange" href="/collection/">EXPLORE COLLECTION ↗︎</a>')}</div>`}<div class="panel" style="margin-top:24px"><div class="panel-head"><h2>YOUR RECENT ORDERS</h2><button class="text-btn" data-tab="orders">View all ↗︎</button></div>${orderList(state.orders.slice(0,3))}</div></div><div class="stack"><section class="panel orange-panel"><p class="eyebrow">A NOTE FOR YOUR EVERYDAY</p><h2>FEWER THINGS.<br>BETTER<br>FEELINGS.</h2><p class="small">Build a wardrobe that feels like you. Start with one good piece.</p><a class="btn" href="/collection/">FIND YOUR PIECE ↗︎</a></section><section class="dashboard-studio"><div><p class="eyebrow">THE STYLE STUDIO</p><h2>A LITTLE<br>DIRECTION.</h2><p>New day. New way to wear it.</p><a href="/studio/">Build my next look ↗︎</a></div><img src="/assets/tee-front.png" alt="Black Lyverne Signature Tee"></section></div></div>`;
}
function trackingCard(order){const index=statuses.indexOf(order.status),progress=Math.max(0,index)/4*100;const item=order.items[0];return `<section class="tracking-card"><div class="tracking-top"><span class="eyebrow">ORDER ${e(order.id)}</span>${badge(order.status)}</div><div class="tracking-body">${image(item)}<div><p class="eyebrow">${order.status==='delivered'?'WELCOME TO YOUR EVERYDAY.':order.status==='cancelled'?'ORDER CANCELLED':order.status==='confirmed'?'WE’VE GOT YOUR REQUEST.':'GOOD THINGS ARE COMING.'}</p><h2>${e(item.name)}</h2><p>${e(item.color)} · ${e(item.size)} · ${order.items.reduce((s,i)=>s+i.quantity,0)} piece(s)</p><p class="muted small">${order.delivery_date&&order.status!=='cancelled'?'Estimated arrival: '+date(order.delivery_date):'Delivery date will be confirmed by the store.'}</p></div></div>${order.status!=='cancelled'?`<div class="track" style="--progress:${progress}%" aria-label="Order progress: ${e(statusLabels[order.status])}">${statuses.map((s,i)=>`<div class="step ${i<=index?'done':''} ${i===index?'current':''}"><i aria-hidden="true"></i><span>${e(statusLabels[s])}</span></div>`).join('')}</div>`:''}<div class="track-note"><span>${demo?'SAMPLE JOURNEY':`CHECKED ${state.lastCheck?.toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit'})||'NOW'} · REFRESHES EVERY 15 SECONDS`}</span><button class="text-btn" data-track="${e(order.id)}">Full journey ↗︎</button></div></section>`;}
function orderList(orders){if(!orders.length)return '<p class="muted small">Your orders will appear here.</p>';return orders.map(o=>`<div class="inventory-row"><div><strong>${e(o.id)}</strong><span>${e(o.items[0]?.name)} · ${date(o.created_at)}</span></div><div>${badge(o.status)}<span>${money(o.total)}</span></div><button class="text-btn" data-${isAdmin?'order':'track'}="${e(o.id)}">View ↗︎</button></div>`).join('');}
function ordersView(){const list=filteredOrders();return heading(isAdmin?'EVERY ORDER.':'YOUR ORDERS.',isAdmin?'From the first confirmation to their front door.':'Every piece. Every step.',isAdmin?button('EXPORT CSV ↓','export-orders','btn ghost'):button('ORDER FROM MY BAG ↗︎','checkout','btn orange'))+`<div class="toolbar"><label class="sr-only" for="search">Search orders</label><input id="search" data-search placeholder="Search order or customer…" value="${e(state.query)}"><label class="sr-only" for="status-filter">Order status</label><select id="status-filter" data-filter><option value="all">All statuses</option>${[...statuses,'cancelled'].map(s=>`<option value="${s}" ${s===state.filter?'selected':''}>${statusLabels[s]}</option>`).join('')}</select></div><div id="list-results">${ordersTable(list)}</div>`;}
function filteredTeam(){const q=state.teamQuery.trim().toLowerCase();return q?state.team.filter(u=>`${u.name||''} ${u.email||''}`.toLowerCase().includes(q)):state.team;}
function filteredOrders(){return state.orders.filter(o=>(state.filter==='all'||o.status===state.filter)&&`${o.id} ${o.customer_name||''} ${o.customer_email||''}`.toLowerCase().includes(state.query.toLowerCase()));}
function ordersTable(list){if(!list.length)return empty('NO ORDERS HERE YET.','Try another filter, or come back after the first order.');return `<div class="table-wrap"><table><thead><tr><th>ORDER</th><th>${isAdmin?'CUSTOMER':'PIECES'}</th><th>STATUS</th><th>PAYMENT</th><th>TOTAL</th><th></th></tr></thead><tbody>${list.map(o=>`<tr><td><strong>${e(o.id)}</strong><small>${date(o.created_at)}</small></td><td>${e(isAdmin?o.customer_name:o.items[0]?.name)}<small>${e(isAdmin?(o.district?o.district+' · '+o.phone:o.customer_email):o.items[0]?.color)}</small></td><td>${badge(o.status)}</td><td>${badge(o.payment)}</td><td>${money(o.total)}${o.discount?`<small>${e(o.promo_code)} · saved ${money(o.discount)}</small>`:''}</td><td><button class="text-btn" data-${isAdmin?'order':'track'}="${e(o.id)}">${isAdmin?'Manage':'Track'} ↗︎</button></td></tr>`).join('')}</tbody></table></div>`;}
function trackingView(){const order=state.orders.find(o=>o.id===state.selectedOrder)||state.orders[0];return heading('FOLLOW THE FEELING.','Your parcel’s journey, one confirmed step at a time.',button('REFRESH ↻','refresh-tracking','btn ghost'))+(order?`<label class="order-select">Choose an order<select id="tracking-order">${state.orders.map(o=>`<option value="${e(o.id)}" ${o.id===order.id?'selected':''}>${e(o.id)} · ${e(o.items[0].name)}</option>`).join('')}</select></label><div class="track-detail"><div>${trackingCard(order)}<div class="panel" style="margin-top:24px"><div class="panel-head"><h2>THE DELIVERY DETAILS</h2></div><p>${e(order.address)}</p><p>${[order.thana,order.district,order.division].filter(Boolean).map(e).join(' · ')}${order.postcode?' · '+e(order.postcode):''}</p><p class="small muted">${e(order.phone)}</p><div class="settings-row"><div><strong>${e(order.carrier||'Delivery partner pending')}</strong><p>${e(order.tracking_number||'Tracking number will appear after dispatch.')}</p></div></div><p class="metric-note">Updates are confirmed by Lyverne. Courier GPS is not connected.</p></div></div><section class="panel"><div class="panel-head"><h2>YOUR PARCEL’S STORY</h2></div><ol class="timeline">${state.events.map(ev=>`<li><strong>${e(statusLabels[ev.status]||ev.status)}</strong>${e(ev.message)}<time>${time(ev.created_at)}</time></li>`).join('')||'<li>Order history is loading.</li>'}</ol></section></div>`:empty('A JOURNEY STARTS WITH A PIECE.','Your delivery timeline will appear after your first order.','<a class="btn orange" href="/collection/">Explore the collection ↗︎</a>'));}
function wishlist(){try{return JSON.parse(state.user.wishlist||'[]');}catch{return [];}}
function savedView(){const saved=wishlist(),products=[...originals,...state.products.filter(p=>!originals.some(o=>o.id===p.id))];return heading('THE GOOD ONES.','Keep the pieces you come back to.')+`<div class="products-cards">${products.map(p=>`<article class="saved-card">${image(p)}<h3>${e(p.name)}</h3><p class="small muted">${e(p.color)}</p><div class="actions"><button class="text-btn" data-save="${e(p.id)}" aria-pressed="${saved.includes(p.id)}">${saved.includes(p.id)?'♥ Saved · remove':'♡ Save piece'}</button></div></article>`).join('')}</div>`;}
function profileView(){return heading('MAKE IT YOURS.','The details that help us look after your everyday.')+`<form id="profile-form" class="profile-form"><label>Your name<input name="name" value="${e(state.user.name)}" autocomplete="name" maxlength="100" required></label><label>Email address<input value="${e(state.user.email)}" type="email" disabled></label><p class="small muted">Your email is managed by your sign-in provider.</p><label>Phone number<input name="phone" value="${e(state.user.phone)}" autocomplete="tel" maxlength="40"></label><p class="error" role="alert"></p><div><button class="btn orange">SAVE DETAILS ↗︎</button></div></form>`;}
function addressesView(){return heading('HOME IS WHERE<br>THE PARCEL GOES.','Your default delivery details. You can change these before every order.')+`<form id="address-form" class="profile-form"><label>Street address<textarea name="address" autocomplete="street-address" rows="3" maxlength="700" required>${e(state.user.address)}</textarea></label><div class="form-grid"><label>City<input name="city" value="${e(state.user.city)}" autocomplete="address-level2" maxlength="100" required></label><label>Postal code<input name="postcode" value="${e(state.user.postcode)}" autocomplete="postal-code" maxlength="20"></label></div><label>Delivery phone<input name="phone" value="${e(state.user.phone)}" autocomplete="tel" maxlength="40" required></label><p class="error" role="alert"></p><div><button class="btn orange">SAVE DELIVERY DETAILS ↗︎</button></div></form>`;}
function adminOverview(){const m=analytics(state.orders,state.products,state.days);return heading('YOUR STORE TODAY.','Here’s how your everyday is moving.',`<button class="btn ghost" data-tab="promotions">PROMO CODES ↗︎</button>${button('CREATE PRODUCT ＋','new-product','btn orange')}`)+stats([['Recorded paid sales',money(m.revenue),'Last 30 days · BDT'],['Orders',m.count,`${m.open} still in progress`],['Average paid order',money(m.average),'Excludes cancellations'],['Stock attention',m.lowStock.length,'Active pieces below 6 units']])+`<div class="dash-grid"><div class="stack"><section class="panel"><div class="panel-head"><h2>THE WEEK IN VIEW</h2><button class="text-btn" data-tab="analytics">See analytics ↗︎</button></div>${chart(m)}</section><section class="panel"><div class="panel-head"><h2>THE LATEST ORDERS</h2><button class="text-btn" data-tab="orders">View all ↗︎</button></div>${orderList(state.orders.slice(0,4))}</section></div><div class="stack"><section class="panel orange-panel"><p class="eyebrow">YOUR BUSINESS COMPANION / ✳</p><h2>A LITTLE<br>MORE CLARITY.</h2><p class="small">${e(insights(m)[0].body)}</p><button class="btn" data-tab="assistant">OPEN COMPANION ↗︎</button></section><section class="panel"><div class="panel-head"><h2>KEEP AN EYE ON</h2></div>${m.lowStock.length?m.lowStock.slice(0,4).map(p=>`<div class="inventory-row"><div>${e(p.name)}<span>${e(p.color)}</span></div><strong>${p.stock} left</strong></div>`).join(''):'<p class="muted small">No active products are below the stock threshold.</p>'}<button class="text-btn" data-tab="inventory">Manage inventory ↗︎</button></section></div></div>`;}
function chart(m){const max=Math.max(1,...m.weeks.map(d=>d.value));return `<div class="chart" role="img" aria-label="Recorded paid sales by day: ${m.weeks.map(d=>d.label+' '+money(d.value)).join(', ')}">${m.weeks.map(d=>`<div class="chart-column"><b>${d.value?money(d.value):'—'}</b><i style="height:${d.value/max*80}%"></i><span>${d.label}</span></div>`).join('')}</div><div class="chart-caption"><span>LAST 7 DAYS · UTC</span><span>RECORDED PAYMENTS / BDT</span></div>`;}
function productsView(){return heading('THE PIECES.','Create, edit and publish your collection.',button('CREATE PRODUCT ＋','new-product','btn orange'))+`<div class="toolbar"><input aria-label="Search products" data-search placeholder="Search a name or color…" value="${e(state.query)}"><select aria-label="Product status" data-filter><option value="all">All products</option>${['active','draft','archived'].map(s=>`<option ${s===state.filter?'selected':''}>${s}</option>`).join('')}</select>${originals.some(o=>!state.products.some(p=>p.id===o.id))?button('IMPORT LYVERNE COLLECTION','import','btn ghost'):''}</div><div id="list-results">${productsTable()}</div>`;}
function productsTable(){const list=state.products.filter(p=>(state.filter==='all'||p.status===state.filter)&&`${p.name} ${p.color}`.toLowerCase().includes(state.query.toLowerCase()));return list.length?`<div class="table-wrap"><table><thead><tr><th>PRODUCT</th><th>PRICE</th><th>STOCK</th><th>STATUS</th><th>ACTIONS</th></tr></thead><tbody>${list.map(p=>`<tr><td><div class="table-product">${image(p)}<div><strong>${e(p.name)}</strong><small>${e(p.color)}</small></div></div></td><td>${money(p.price)}</td><td>${p.stock}</td><td>${badge(p.status)}</td><td><div class="table-actions"><button class="text-btn" data-edit="${e(p.id)}">Edit ↗︎</button>${p.status!=='archived'?`<button class="text-btn" data-archive="${e(p.id)}">Archive</button>`:''}</div></td></tr>`).join('')}</tbody></table></div>`:empty('ROOM FOR THE NEXT FAVORITE.','Create a product, or import the existing collection as drafts.');}
function inventoryView(){return heading('EVERY PIECE COUNTS.','Available units across each product’s offered sizes. Orders reserve stock automatically.')+`<div class="table-wrap"><table><thead><tr><th>PIECE</th><th>AVAILABLE UNITS</th><th>SIZES OFFERED</th><th>STATUS</th><th></th></tr></thead><tbody>${state.products.filter(p=>p.status!=='archived').map(p=>`<tr><td><div class="table-product">${image(p)}<div>${e(p.name)}<small>${e(p.color)}</small></div></div></td><td>${p.stock} ${p.stock<6?badge('pending','LOW STOCK'):''}</td><td>${p.sizes.join(' / ')}</td><td>${badge(p.status)}</td><td><button class="text-btn" data-edit="${e(p.id)}">Adjust ↗︎</button></td></tr>`).join('')||'<tr><td colspan="5">Import or create your first product to begin.</td></tr>'}</tbody></table></div><p class="metric-note">Stock is tracked per colorway, not per size. Archived products remain recoverable. Cancelling an order returns its reserved units.</p>`;}
function customersView(){return heading('THE PEOPLE<br>BEHIND THE PIECES.','Customers who have joined your Lyverne circle.')+`<div class="table-wrap"><table><thead><tr><th>CUSTOMER</th><th>LOCATION</th><th>ORDERS</th><th>RECORDED SPEND</th><th>JOINED</th></tr></thead><tbody>${state.customers.map(c=>{const orders=state.orders.filter(o=>o.customer_id===c.id);return `<tr><td><strong>${e(c.name)}</strong><small>${e(c.email)}</small></td><td>${e(c.city||'Not provided')}</td><td>${orders.length}</td><td>${money(orders.filter(o=>o.payment==='paid'&&o.status!=='cancelled').reduce((s,o)=>s+o.total,0))}</td><td>${date(c.created_at)}</td></tr>`;}).join('')}</tbody></table></div>`;}
function analyticsView(){const m=analytics(state.orders,state.products,state.days);return heading('LESS GUESSWORK.<br>MORE PERSPECTIVE.','Sales and operations, drawn from your store records.',`<select id="analytics-period" aria-label="Analytics period">${[7,30,90].map(n=>`<option value="${n}" ${n===state.days?'selected':''}>Last ${n} days</option>`).join('')}</select>`)+stats([['Recorded paid sales',money(m.revenue),`Last ${state.days} days`],['Orders received',m.count,`${m.paid} with payment recorded`],['Average paid order',money(m.average),'Paid, non-cancelled orders'],['In progress',m.open,'Across all dates']])+`<div class="lower-grid"><section class="panel"><div class="panel-head"><h2>PAID SALES / THIS WEEK</h2></div>${chart(m)}</section><section class="panel"><div class="panel-head"><h2>THE PIECES PEOPLE PICK</h2></div>${m.top.length?m.top.map(p=>`<div class="inventory-row"><div>${e(p.name)}<span>${p.quantity} units</span></div><strong>${money(p.revenue)}</strong></div>`).join(''):'<p class="muted">Your paid sales will appear here.</p>'}</section></div><div class="panel" style="margin-top:24px"><div class="panel-head"><h2>WHAT THE NUMBERS SAY</h2></div>${insights(m).map(n=>`<article class="insight-item"><h3>${e(n.title)}</h3><p>${e(n.body)}</p></article>`).join('')}</div><p class="metric-note">These are recorded order payments, not a payment-provider reconciliation. Costs, margins, ad spend and website conversion are not connected.</p>`;}
function assistantView(){const m=analytics(state.orders,state.products),connected=state.connections.ai&&!demo;return heading('YOUR SECOND<br>PAIR OF EYES.','A clearer view of what needs your attention.')+`<div class="assistant-panel"><section class="panel"><div class="assistant-intro"><img src="/assets/lyverne-monogram.png" alt=""><div><strong>LYVERNE BUSINESS COMPANION</strong><br><span>${connected?'AI connected · suggestions only':'Store-data insights · live AI not connected'}</span></div></div><form id="assistant-form" class="assistant-question"><label for="business-prompt">What would you like to understand?</label><textarea id="business-prompt" name="prompt" rows="4" maxlength="1500" required placeholder="What should I focus on this week?"></textarea><div class="prompt-list"><button type="button" data-prompt="What needs attention in my inventory?">Check my inventory</button><button type="button" data-prompt="Summarize sales and the next three actions.">Find my next steps</button><button type="button" data-prompt="Which products should I focus on?">Understand product demand</button></div><button class="btn orange">${connected?'ASK THE COMPANION':'REVIEW STORE INSIGHTS'} ✳</button><p class="error" role="alert"></p></form><div id="assistant-answer" role="status" class="assistant-reply">${e(insights(m).map(n=>n.title+'\n'+n.body).join('\n\n'))}</div><p class="small muted">The companion suggests actions. It never changes products, orders, or prices for you.</p></section><div class="stack"><section class="panel orange-panel"><p class="eyebrow">A BETTER BUSINESS HABIT</p><h2>NOTICE.<br>UNDERSTAND.<br>THEN ACT.</h2><p>Start with your stock and open orders. A useful next step beats a hundred numbers.</p></section><section class="panel"><h3>WHAT IT CAN SEE</h3><p class="metric-note">Aggregate sales, product performance, stock counts and open-order totals. Customer names, emails and delivery addresses are excluded from AI requests.</p><button class="text-btn" data-tab="settings">View connections ↗︎</button></section></div></div>`;}
function activityView(){return heading('NOTHING GETS LOST.','A timestamped record of changes made in your store admin.')+`<section class="panel"><ul class="activity-list">${state.activity.map(a=>`<li><strong>${e(a.action)}</strong> · ${e(a.target)}<time>${time(a.created_at)} · ${e(a.actor_name||'Store owner')}</time></li>`).join('')||'<li>Your first product or order update will appear here.</li>'}</ul></section>`;}
function settingsView(){return heading('STORE ADMIN.','Your store setup and connection status.')+`<section class="panel"><div class="settings-row"><div><strong>Account access</strong><p>Customer sign-in through ChatGPT. Admin access is checked on the server for the store owner.</p></div>${badge('active','CONNECTED')}</div><div class="settings-row"><div><strong>Products, orders & customers</strong><p>Persistent store records. Stock is reserved when an order is requested.</p></div>${badge(demo?'demo':'active',demo?'SAMPLE':'CONNECTED')}</div><div class="settings-row"><div><strong>Business AI</strong><p>${state.connections.ai?'AI answers use aggregate store data.':'Store-data insights work now. A private AI service key is needed for conversational answers.'}</p></div>${badge(state.connections.ai?'active':'draft',state.connections.ai?'CONNECTED':'NOT CONNECTED')}</div><div class="settings-row"><div><strong>Courier integration</strong><p>Customers receive your recorded order updates. Courier location and automatic carrier events need a delivery service connection.</p></div>${badge('draft','NOT CONNECTED')}</div><div class="settings-row"><div><strong>Payment collection</strong><p>Order requests do not charge customers. Payments can be recorded manually after confirmation.</p></div>${badge('draft','NOT CONNECTED')}</div><div class="settings-row"><div><strong>Product image uploads</strong><p>PNG, JPEG and WebP images up to 5 MB.</p></div>${badge(state.connections.uploads?'active':'draft',state.connections.uploads?'CONNECTED':'NOT CONNECTED')}</div></section>`;}
function openEditor(html){$('#editor-content').innerHTML=html;$('#editor').showModal();}
function closeEditor(){$('#editor').close();}
function editorHeading(title){return `<div class="editor-heading"><h2>${title}</h2><button class="editor-close" data-action="close-editor" aria-label="Close dialog">×</button></div>`;}
function productEditor(pid){const p=state.products.find(p=>p.id===pid)||{home_slot:0,name:'',color:'',description:'',category:'SIGNATURE',price:'',stock:0,sizes:['M','L','XL'],image:'/assets/tee-front.png',back:'',status:'draft'};openEditor(`${editorHeading(pid?'EDIT THE PIECE.':'MAKE SOMETHING GOOD.')}<form id="product-form" data-id="${e(pid||'')}" data-version="${p.version||''}"><div class="form-grid"><label>Product name<input name="name" maxlength="100" value="${e(p.name)}" required></label><label>Color<input name="color" maxlength="60" value="${e(p.color)}" required></label><label>Price (BDT)<input name="price" type="number" min="1" max="1000000" step="1" value="${p.price??''}" placeholder="Leave blank for TBA"></label><label>Available units<input name="stock" type="number" min="0" max="100000" value="${p.stock}" required></label><label>Collection<input name="category" maxlength="60" value="${e(p.category)}" required></label><label>Status<select name="status">${['draft','active','archived'].map(s=>`<option ${p.status===s?'selected':''}>${s}</option>`).join('')}</select></label><label>Homepage position<select name="home_slot">${[0,1,2,3,4,5,6].map(n=>`<option value="${n}" ${Number(p.home_slot||0)===n?'selected':''}>${n===0?'Not on the homepage':'Position '+n}</option>`).join('')}</select></label><label class="full">Description<textarea name="description" rows="3" maxlength="2000" required>${e(p.description)}</textarea></label><fieldset class="full"><legend>Sizes offered</legend><div class="actions">${['S','M','L','XL','XXL'].map(s=>`<label class="checkbox"><input type="checkbox" name="sizes" value="${s}" ${p.sizes.includes(s)?'checked':''}>${s}</label>`).join('')}</div></fieldset><label class="full">Front image<input name="image" value="${e(p.image)}" readonly required></label><div class="image-picker full">${originals.map(o=>`<button type="button" data-image="${o.image}" aria-label="Use ${e(o.name+' '+o.color)} image" aria-pressed="${p.image===o.image}">${image(o)}</button>`).join('')}</div><label class="full">Upload a front image<input id="product-upload" type="file" accept="image/png,image/jpeg,image/webp"></label><label class="full">Back image (optional)<select name="back"><option value="">No back image</option>${originals.filter(o=>o.back).map(o=>`<option value="${o.back}" ${p.back===o.back?'selected':''}>${e(o.name+' / '+o.color)}</option>`).join('')}</select></label></div><p class="small muted">Publishing makes this piece visible in the live collection. Stock is shared across the offered sizes. A homepage position puts the piece in the EXPLORE ALL COLORS grid on the front page, left to right; only published pieces can go there.</p><p class="error" role="alert"></p><div class="actions"><button type="button" class="btn ghost" data-action="close-editor">Cancel</button><button class="btn orange">SAVE PRODUCT ↗︎</button></div></form>`);}
async function orderEditor(oid){const local=state.orders.find(o=>o.id===oid);const data=await api('/api/admin/orders/'+encodeURIComponent(oid));const o=data.order;openEditor(`${editorHeading('ORDER '+e(o.id))}<p class="small">${e(local?.customer_name||'Customer')} · ${money(o.total)}</p><div class="order-delivery"><div><span class="eyebrow">DELIVER TO</span><p>${e(o.address)}</p><p>${[o.thana,o.district,o.division].filter(Boolean).map(e).join(' · ')||'<span class="muted">Placed before delivery regions were collected</span>'}${o.postcode?' · '+e(o.postcode):''}</p></div><div><span class="eyebrow">PHONE</span><p><a href="tel:${e(o.phone)}">${e(o.phone)||'Not given'}</a></p><button type="button" class="text-btn" data-copy-address="${e(oid)}">Copy address ⧉</button></div></div><div class="inventory-list">${o.items.map(i=>`<div class="inventory-row"><div>${e(i.name)}<span>${e(i.color)} · ${e(i.size)} × ${i.quantity}</span></div>${money(i.price*i.quantity)}</div>`).join('')}</div>${o.discount?`<div class="checkout-totals"><div><span>Merchandise subtotal</span><span>${money(o.subtotal??o.total+o.discount)}</span></div><div><span>${e(o.promo_code)}</span><span>−${money(o.discount)}</span></div><div><span>Merchandise total</span><span>${money(o.total)}</span></div></div>`:''}<form id="order-form" data-id="${e(oid)}" data-version="${o.version}"><div class="form-grid"><label>Order stage<select name="status">${[...statuses,'cancelled'].filter(s=>s===o.status||(o.status!=='cancelled'&&o.status!=='delivered'&&(s==='cancelled'||statuses.indexOf(s)===statuses.indexOf(o.status)+1))).map(s=>`<option value="${s}" ${s===o.status?'selected':''}>${statusLabels[s]}</option>`).join('')}</select></label><label>Payment record<select name="payment">${['pending','paid','refunded'].map(s=>`<option ${o.payment===s?'selected':''}>${s}</option>`).join('')}</select></label><label>Delivery partner<input name="carrier" maxlength="80" value="${e(o.carrier)}"></label><label>Tracking number<input name="tracking_number" maxlength="100" value="${e(o.tracking_number)}"></label><label>Estimated delivery<input name="delivery_date" type="date" value="${e(o.delivery_date)}"></label><label>Internal note<input name="note" maxlength="500" value="${e(o.note)}"></label><label class="full">Update for the customer<textarea name="message" rows="2" maxlength="500" placeholder="Your pieces are packed and ready to go."></textarea></label></div><p class="small muted">This updates the customer’s timeline. Recording a payment does not charge or refund money.</p><p class="error" role="alert"></p><div class="actions"><button class="btn orange">SAVE ORDER UPDATE ↗︎</button></div></form><details><summary>Order history</summary><ul class="activity-list">${data.events.map(ev=>`<li>${e(ev.message)}<time>${time(ev.created_at)}</time></li>`).join('')}</ul></details>`);}
// The division/district pair comes from the server, which is also what
// validates it, so the dropdown and the rule behind it can never drift apart.
function districtOptions(division,selected=''){
 const list=(state.regions&&state.regions[division])||[];
 return '<option value="">'+(list.length?'Select your district':'Choose a division first')+'</option>'
  +list.map(d=>`<option value="${e(d)}" ${d===selected?'selected':''}>${e(d)}</option>`).join('');
}
async function checkout(){
 if(demo){notify('Sign in to request an order from your bag.');return;}
 let items=[],pendingCode='';try{items=JSON.parse(localStorage.getItem('lyverne-bag')||'[]');pendingCode=localStorage.getItem('lyverne-promo-code')||'';}catch{}
 if(!Array.isArray(items)||!items.length){notify('Your bag is empty. Add a piece from the collection first.');return;}
 state.checkout={items,quote:null,sequence:0};
 // The saved profile has no division or district yet, so those start empty and
 // the rest is prefilled from it.
 if(!state.regions){try{state.regions=(await api('/api/regions')).divisions;}catch{state.regions={};}}
 const divisions=Object.keys(state.regions||{});
 openEditor(`${editorHeading('YOUR NEXT EVERYDAY.')}<p>Review your pieces and your offer. Payment and delivery are confirmed after your request.</p><div id="checkout-summary" aria-live="polite"><p class="muted">Checking your bag…</p></div><form id="checkout-form"><div class="form-grid"><label>Division<select name="division" required><option value="">Select your division</option>${divisions.map(d=>`<option value="${e(d)}">${e(d)}</option>`).join('')}</select></label><label>District<select name="district" required>${districtOptions('')}</select></label><label>Upazila or thana<input name="thana" maxlength="60" value="${e(state.user.city)}" placeholder="Dhanmondi" required></label><label>Postcode <span class="muted">(optional)</span><input name="postcode" maxlength="4" inputmode="numeric" pattern="[0-9]{4}" value="${e(state.user.postcode)}" placeholder="1205"></label><label class="full">House, road and area<textarea name="address" rows="3" minlength="10" maxlength="1000" autocomplete="street-address" placeholder="House 4, Road 12, Dhanmondi" required>${e(state.user.address)}</textarea></label><label class="full">Mobile number<input name="phone" maxlength="20" inputmode="tel" value="${e(state.user.phone)}" autocomplete="tel" placeholder="01712 345678" required></label></div><p class="small muted">We call this number to confirm your order before it is sent.</p><div><div class="promo-entry"><label>Promo code<input name="promoCode" maxlength="24" value="${e(pendingCode)}" placeholder="Enter your code" autocomplete="off" autocapitalize="characters"></label><button type="button" class="btn" data-action="apply-promo">Apply</button><button type="button" class="text-btn" data-action="remove-promo">Remove</button></div><p class="promo-feedback" id="promo-feedback" role="status"></p></div><div id="checkout-totals"></div><p class="small muted">No payment is taken here. Shipping costs and delivery availability are confirmed by the store.</p><p class="error" role="alert"></p><button type="submit" class="btn orange checkout-submit" disabled>REQUEST MY ORDER ↗︎</button></form>`);
 await refreshQuote(pendingCode);
}
async function refreshQuote(code=''){
 const checkout=state.checkout,sequence=++checkout.sequence,feedback=$('#promo-feedback'),submit=$('.checkout-submit');
 submit.disabled=true;checkout.quote=null;feedback.textContent='Checking the latest price…';feedback.classList.remove('is-error');
 try{
  const {quote}=await api('/api/checkout/quote',{method:'POST',body:JSON.stringify({items:checkout.items,promoCode:code})});
  if(state.checkout!==checkout||sequence!==checkout.sequence||!$('#checkout-form'))return;
  checkout.quote=quote;
  $('#checkout-summary').innerHTML=`<div class="checkout-items">${quote.items.map(i=>`<div class="checkout-item"><img src="${e(i.image)}" alt="${e(i.name)}"><div><strong>${e(i.name)}</strong><small>${e(i.color)} / ${e(i.size)} × ${i.quantity}</small></div><span>${money(i.price*i.quantity)}</span></div>`).join('')}</div>`;
  $('#checkout-totals').innerHTML=`<div class="checkout-totals"><div><span>Merchandise subtotal</span><span>${money(quote.subtotal)}</span></div>${quote.discount?`<div><span>${e(quote.promo_code)}</span><span>−${money(quote.discount)}</span></div>`:''}<div><span>Merchandise total</span><span>${money(quote.total)}</span></div></div>`;
  $('#checkout-form [name=promoCode]').value=quote.promo_code;
  feedback.textContent=quote.promo_code?`${quote.promo_code} applied. You save ${money(quote.discount)}.`:'One promo code can be applied per order.';
  submit.disabled=false;
 }catch(error){
  if(state.checkout!==checkout||sequence!==checkout.sequence||!$('#checkout-form'))return;
  feedback.textContent=error.message;feedback.classList.add('is-error');$('#checkout-totals').innerHTML='';
 }
}

async function refreshTracking(){if(document.hidden||document.activeElement?.matches('input,select,textarea')||$('#editor').open){timer=setTimeout(refreshTracking,15000);return;}try{await loadTracking();if(['overview','tracking','orders'].includes(state.view)){const scroll=scrollY;render();window.scrollTo(0,scroll);}}catch{notify('Could not refresh tracking. Your last confirmed update is still shown.');timer=setTimeout(refreshTracking,30000);}}
// Whether the signed-in person is the chief comes from the server on every
// team request, never from a local flag -- the sidebar must not be able to
// talk itself into showing controls the server would refuse.
function teamContext(){return {chief:!!state.user?.chief,youId:state.user?.id||'',query:state.teamQuery};}
// The team tabs are loaded when opened rather than with the rest of the
// dashboard, so the common case -- an admin checking orders -- stays one round
// trip and does not pull the staff thread down with it.
async function loadTeam(view){
 if(demo)return;
 if(view==='team'){const d=await api('/api/admin/users');state.team=d.users;state.user.chief=d.you.chief;return;}
 if(view==='tasks'){const d=await api('/api/admin/tasks');state.tasks=d.tasks;state.staff=d.team;return;}
 if(view==='chat'){const d=await api('/api/admin/messages');state.messages=d.messages;return;}
}
const TEAM_VIEWS=['team','tasks','chat'];
function scrollChat(){const thread=$('#chat-thread');if(thread)thread.scrollTop=thread.scrollHeight;}
async function navigate(tab){if(tab==='promotions'&&!demo)await loadData();if(TEAM_VIEWS.includes(tab))await loadTeam(tab);state.view=tab;state.query='';state.filter='all';history.replaceState(null,'','#'+tab);render();$('#workspace-main').scrollIntoView({behavior:'instant',block:'start'});}
async function action(name){if(name==='retry'){boot();return;}if(name==='close-editor'){closeEditor();return;}if(name==='new-product'){productEditor();return;}
 if(name==='refresh-promotions'){if(!demo)await loadData();render();notify('Promotion performance refreshed.');return;}
 if(name==='new-promo'){openEditor(promoForm());return;}
 if(name==='preview-promotion'){const form=$('#campaign-form'),campaign={...state.campaign,...Object.fromEntries(new FormData(form))};const offer=state.promotions.find(p=>p.code===campaign.code);showPromotion({...campaign,offer},{preview:true});return;}
 if(name==='apply-promo'){await refreshQuote($('#checkout-form [name=promoCode]').value);return;}
 if(name==='remove-promo'){$('#checkout-form [name=promoCode]').value='';try{localStorage.removeItem('lyverne-promo-code');}catch{}await refreshQuote('');return;}if(name==='checkout'){checkout();return;}if(name==='refresh-tracking'){if(state.selectedOrder){await loadTracking();render();notify('Showing the latest confirmed update.');}return;}if(name==='import'){if(!writeAllowed())return;await api('/api/admin/import',{method:'POST',body:'{}'});await loadData();render();notify('Original collection imported as drafts. Set prices and stock before publishing.');return;}if(name==='export-orders'){const safe=v=>'"'+String(v??'').replace(/^[=+@-]/,"'").replaceAll('"','""')+'"';const csv=[['Order','Date','Status','Payment','Total BDT'],...filteredOrders().map(o=>[o.id,o.created_at,o.status,o.payment,o.total])].map(r=>r.map(safe).join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));const a=document.createElement('a');a.href=url;a.download='lyverne-orders.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);return;}}
document.addEventListener('click',async ev=>{const target=ev.target.closest('button,a');if(!target)return;
 if(target.dataset.mode){authMode=target.dataset.mode;renderAuth();return;}
 if(target.dataset.action==='google'){ev.preventDefault();try{await auth.signInWithGoogle(location.origin+'/login/'+(new URLSearchParams(location.search).get('return_to')?location.search:''));}catch(err){notify(err.message);}return;}
 if(target.dataset.action==='sign-out'){ev.preventDefault();await auth.signOut();location.assign('/login/');return;}
 if(target.dataset.action==='forgot'){ev.preventDefault();const email=$('#auth-password input[name=email]')?.value?.trim();if(!email){notify('Enter your email address first, then choose this again.');return;}try{await auth.sendPasswordReset({email,redirectTo:location.origin+'/login/'});notify('If that address has an account, a reset link is on its way.');}catch(err){notify(err.message);}return;}
 try{
 if(target.dataset.action){ev.preventDefault();await action(target.dataset.action);}
 if(target.dataset.tab){ev.preventDefault();await navigate(target.dataset.tab);}
 if(target.dataset.track){state.selectedOrder=target.dataset.track;await loadTracking();await navigate('tracking');}
 if(target.dataset.edit)productEditor(target.dataset.edit);
 if(target.dataset.promoOrders){const p=state.promotions.find(p=>p.id===target.dataset.promoOrders);openEditor(promotionOrders(p,promoReport(),money,Math.max(0,Number(target.dataset.promoPage)||0)));}
 if(target.dataset.promoEdit)openEditor(promoForm(state.promotions.find(p=>p.id===target.dataset.promoEdit)));
 if(target.dataset.order)await orderEditor(target.dataset.order);
 if(target.dataset.archive){const p=state.products.find(p=>p.id===target.dataset.archive);openEditor(`${editorHeading('ARCHIVE THIS PIECE?')}<p>${e(p.name)} will leave the live collection. You can restore it by editing its status later.</p><form id="archive-form" data-id="${e(p.id)}" data-version="${p.version}"><p class="error" role="alert"></p><div class="actions"><button type="button" class="btn ghost" data-action="close-editor">Keep it</button><button class="btn">ARCHIVE PRODUCT</button></div></form>`);}
 if(target.dataset.save){if(!writeAllowed())return;let items=wishlist();items=items.includes(target.dataset.save)?items.filter(i=>i!==target.dataset.save):[...items,target.dataset.save];await api('/api/wishlist',{method:'PUT',body:JSON.stringify({items})});state.user.wishlist=JSON.stringify(items);render();notify('Your saved pieces are updated.');}
 if(target.dataset.image){$('#product-form [name=image]').value=target.dataset.image;$$('[data-image]').forEach(b=>b.setAttribute('aria-pressed',String(b===target)));}
if(target.dataset.person){const person=state.team.find(u=>u.id===target.dataset.person);if(person)openEditor(personForm(person));}
 if(target.dataset.task&&target.dataset.status){if(!writeAllowed())return;await api('/api/admin/tasks/'+encodeURIComponent(target.dataset.task),{method:'PUT',body:JSON.stringify({status:target.dataset.status})});await loadTeam('tasks');render();notify('Task updated.');}
 if(target.dataset.taskRemove){if(!writeAllowed())return;await api('/api/admin/tasks/'+encodeURIComponent(target.dataset.taskRemove),{method:'DELETE'});await loadTeam('tasks');render();notify('Task removed.');}
 if(target.dataset.refreshChat){await loadTeam('chat');$('#chat-thread').innerHTML=chatMessages(state.messages,state.user.id);scrollChat();}
 if(target.dataset.copyAddress){const block=$('.order-delivery');if(block){const text=[...block.querySelectorAll('p')].map(x=>x.textContent.trim()).filter(Boolean).join('\n');try{await navigator.clipboard.writeText(text);notify('Delivery address copied.');}catch{notify('Select the address and copy it manually.');}}}
 if(target.dataset.prompt){$('#business-prompt').value=target.dataset.prompt;$('#business-prompt').focus();}
 }catch(error){notify(error.message);}});
document.addEventListener('input',ev=>{if(ev.target.matches('[data-team-search]')){state.teamQuery=ev.target.value;$('#team-results').innerHTML=teamRows(filteredTeam(),teamContext());}if(ev.target.id==='promo-search'){state.promoQuery=ev.target.value;refreshPromoRows();}if(ev.target.matches('#checkout-form [name=promoCode]')){$('.checkout-submit').disabled=ev.target.value.trim().toUpperCase()!==state.checkout?.quote?.promo_code;$('#promo-feedback').textContent='Apply your code or remove it before ordering.';}if(ev.target.matches('[data-search]')){state.query=ev.target.value;$('#list-results').innerHTML=state.view==='orders'?ordersTable(filteredOrders()):productsTable();}});
document.addEventListener('change',async ev=>{try{if(ev.target.matches('#checkout-form [name=division]')){const d=$('#checkout-form [name=district]');d.innerHTML=districtOptions(ev.target.value);}if(ev.target.id==='promo-period'){state.promoPeriod=ev.target.value==='all'?'all':Number(ev.target.value);render();}if(ev.target.id==='promo-status'){state.promoFilter=ev.target.value;refreshPromoRows();}if(ev.target.matches('#promo-form [name=kind]')){$('#promo-form [name=value]').max=ev.target.value==='percent'?'100':'1000000';}if(ev.target.matches('[data-filter]')){state.filter=ev.target.value;$('#list-results').innerHTML=state.view==='orders'?ordersTable(filteredOrders()):productsTable();}if(ev.target.id==='analytics-period'){state.days=Number(ev.target.value);render();}if(ev.target.id==='tracking-order'){state.selectedOrder=ev.target.value;await loadTracking();render();}if(ev.target.id==='campaign-upload'){if(!writeAllowed()){ev.target.value='';return;}const file=ev.target.files[0];if(!file)return;if(file.size>5*1024*1024)throw Error('Choose an image under 5 MB.');const result=await api('/api/admin/upload',{method:'POST',body:file});$('#campaign-form [name=image]').value=result.url;const shot=$('#campaign-preview');if(shot)shot.src=result.url;notify('Image uploaded. Save the popup to use it.');}if(ev.target.id==='product-upload'){if(!writeAllowed()){ev.target.value='';return;}const file=ev.target.files[0];if(!file)return;if(file.size>5*1024*1024)throw Error('Choose an image under 5 MB.');const result=await api('/api/admin/upload',{method:'POST',body:file});$('#product-form [name=image]').value=result.url;notify('Image uploaded. Save the product to use it.');}}catch(error){notify(error.message);}});
document.addEventListener('submit',async ev=>{
 const authForm=ev.target.closest('#auth-password,#auth-magic');
 if(authForm){
  ev.preventDefault();
  const data=Object.fromEntries(new FormData(authForm));
  const back=returnTarget();
  await submitAuth(authForm,async()=>{
   if(authForm.id==='auth-magic'){
    await auth.sendMagicLink({email:data.email,redirectTo:location.origin+'/login/'});
    authForm.innerHTML='<p class="auth-copy">Check your inbox. The link signs you in on this device.</p>';
    return;
   }
   if(page==='signup'){
    const {confirmationRequired}=await auth.signUp({email:data.email,password:data.password,name:data.name});
    if(confirmationRequired){authForm.innerHTML='<p class="auth-copy">Almost there. Confirm your email address, then sign in.</p>';return;}
   }else{
    await auth.signIn({email:data.email,password:data.password});
   }
   location.assign(await destinationAfterSignIn());
  });
  return;
 }
 ev.preventDefault();const form=ev.target,submit=$('[type=submit],button:not([type])',form),err=$('.error',form);if(err)err.textContent='';
 if(form.id!=='assistant-form'&&!writeAllowed())return;const fd=new FormData(form),b=Object.fromEntries(fd);if(submit)submit.disabled=true;
 try{
 if(form.id==='signup-form'||form.id==='profile-form'||form.id==='address-form'){const result=await api('/api/me',{method:'PUT',body:JSON.stringify({...state.user,...b})});state.user=result.user;if(form.id==='signup-form'){location.href='/dashboard/';return;}notify('Your details are saved.');}
 if(form.id==='promo-form'){const payload={...b,active:fd.has('active'),version:Number(form.dataset.version)};for(const field of ['starts','ends'])payload[field]=b[field]?new Date(b[field]).toISOString():'';await api('/api/admin/promotions'+(form.dataset.id?'/'+form.dataset.id:''),{method:form.dataset.id?'PUT':'POST',body:JSON.stringify(payload)});closeEditor();await loadData();render();notify('Promo code saved.');}
 if(form.id==='campaign-form'){await api('/api/admin/campaign',{method:'PUT',body:JSON.stringify({...b,enabled:fd.has('enabled'),version:Number(form.dataset.version)})});await loadData();render();notify('Opening promotion saved.');}
 if(form.id==='product-form'){await api('/api/admin/products'+(form.dataset.id?'/'+form.dataset.id:''),{method:form.dataset.id?'PUT':'POST',body:JSON.stringify({...b,sizes:fd.getAll('sizes'),version:Number(form.dataset.version)})});closeEditor();await loadData();render();notify('Product saved.');}
 if(form.id==='archive-form'){await api('/api/admin/products/'+form.dataset.id,{method:'DELETE',body:JSON.stringify({version:Number(form.dataset.version)})});closeEditor();await loadData();render();notify('Product archived. You can restore it from the product editor.');}
 if(form.id==='order-form'){await api('/api/admin/orders/'+form.dataset.id,{method:'PUT',body:JSON.stringify({...b,version:Number(form.dataset.version)})});closeEditor();await loadData();render();notify('Order updated. The customer’s timeline will refresh automatically.');}
 if(form.id==='checkout-form'){
  const checkout=state.checkout;
  if(!checkout?.quote||b.promoCode.trim().toUpperCase()!==checkout.quote.promo_code)throw Error('Apply or remove your promo code before ordering.');
  const result=await api('/api/orders',{method:'POST',body:JSON.stringify({address:b.address,phone:b.phone,division:b.division,district:b.district,thana:b.thana,postcode:b.postcode,items:checkout.items,promoCode:checkout.quote.promo_code,requestKey})});
  try{localStorage.removeItem('lyverne-bag');localStorage.removeItem('lyverne-promo-code');}catch{}
  requestKey=crypto.randomUUID();closeEditor();state.checkout=null;state.selectedOrder=result.order.id;state.orders.unshift(result.order);state.events=[{status:'confirmed',message:'Your order request was received.',created_at:result.order.created_at}];
  try{await loadData();}catch{notify('Your order is saved. Tracking will refresh when the connection returns.');}
  await navigate('tracking');showOrderConfirmation(result.order,money);
 }

 if(form.id==='person-form'){await api('/api/admin/users/'+encodeURIComponent(form.dataset.id),{method:'PUT',body:JSON.stringify({role:b.role,blocked:fd.has('blocked')})});closeEditor();await loadTeam('team');render();notify('Access updated.');}
 if(form.id==='task-form'){await api('/api/admin/tasks',{method:'POST',body:JSON.stringify(b)});form.reset();await loadTeam('tasks');render();notify('Task assigned.');}
 if(form.id==='chat-form'){const text=String(b.body||'').trim();if(!text)throw Error('Write a message first.');await api('/api/admin/messages',{method:'POST',body:JSON.stringify({body:text})});form.reset();await loadTeam('chat');$('#chat-thread').innerHTML=chatMessages(state.messages,state.user.id);scrollChat();$('#chat-body').focus();}
 if(form.id==='assistant-form'){const result=demo?{answer:insights(analytics(state.orders,state.products)).map(n=>n.title+'\n'+n.body).join('\n\n')}:await api('/api/admin/assistant',{method:'POST',body:JSON.stringify(b)});$('#assistant-answer').textContent=result.answer;notify(demo?'Insights from the sample store data.':result.mode==='ai'?'Your business companion has replied.':'Updated insights from your store records.');}
 }catch(error){if(err)err.textContent=error.message;else notify(error.message);}finally{if(submit?.isConnected)submit.disabled=form.id==='checkout-form'&&(!state.checkout?.quote||form.elements.promoCode.value.trim().toUpperCase()!==state.checkout.quote.promo_code);}
});
$('#editor').addEventListener('click',ev=>{if(ev.target===$('#editor')){const r=$('#editor').getBoundingClientRect();if(ev.clientX<r.left||ev.clientX>r.right||ev.clientY<r.top||ev.clientY>r.bottom)closeEditor();}});
document.addEventListener('keydown',ev=>{if(ev.target.id==='chat-body'&&ev.key==='Enter'&&!ev.shiftKey){ev.preventDefault();ev.target.form.requestSubmit();}});
window.addEventListener('hashchange',()=>{state.view=location.hash.slice(1)||'overview';if(state.user)render();});
boot();
